"""Volume 2 · Module 7 « En route ! » (A2)."""
import sys
sys.path.insert(0, '/home/claude/syllabus')
from lib.base import *
from lib.art import *
from lib.module import *
from lib.v2 import CP, CPCOL
from lib.render import to_pdf
from build.v2_m6 import carte

MC = "#1D7874"
TINT = "#E2F2F1"
TRANSP = [("🚆", "le train"), ("🚌", "le bus"), ("🚋", "le tram"), ("🚇", "le métro"), ("🚲", "le vélo"), ("🛴", "la trottinette"), ("🚗", "la voiture"), ("✈️", "l'avion"), ("🚶", "à pied"), ("🚕", "le taxi"), ("⛴️", "le bateau"), ("🚐", "le car (bus de voyage)")]
GARE = [("🎫", "le billet, le ticket"), ("🏧", "le distributeur de billets"), ("🧾", "le guichet"), ("🛤️", "la voie, le quai"), ("🪧", "le panneau d'affichage"), ("⏰", "l'horaire"), ("⏳", "le retard"), ("❌", "supprimé"), ("🔄", "la correspondance"), ("🧳", "les bagages"), ("👮", "le contrôleur"), ("📱", "l'application")]


def panneau(rows, title="DÉPARTS"):
    trs = "".join(f"<tr><td style='color:#FFD166;font-weight:700'>{h}</td><td>{t}</td><td>{d}</td><td style='text-align:center'>{v}</td><td style='color:{'#FF6B6B' if r else '#9EE6A0'}'>{r or 'à l’heure'}</td></tr>" for h, t, d, v, r in rows)
    return (f"<div class='doc' style='transform:none;background:#0B1F3A;color:#fff;border-radius:2mm;padding:3mm;font-family:monospace;font-size:10.5pt'><div style='display:flex;justify-content:space-between'><b style='font-size:14pt;letter-spacing:2px'>{title}</b><span>🕘 09:12</span></div>"
            f"<table style='width:100%;border-collapse:collapse;margin-top:2mm' cellpadding='4'><tr style='color:#9aa1b1;font-size:9pt'><td>Heure</td><td>Train</td><td>Destination</td><td>Voie</td><td>Info</td></tr>{trs}</table></div>")


def build_v2m7(start=1, tstart=1, render=True):
    b = Book("V2 · M7", "Volume 2 · Je me débrouille · Module 7 · En route !", MC, start=start)
    E = Ex(b)
    vis = '<div class="c" style="font-size:36pt;line-height:1.35">🚆🎫⏰🛤️🧳<br>🚌🚋🚲🗺️🎒</div>'
    opening(b, MC, 7, "En route !", vis, [("🎫", "acheter un billet et demander une information"), ("⏰", "comprendre un horaire et une annonce en gare"), ("⏳", "réagir à un retard ou à une suppression"),
            ("🔮", "parler de l'avenir avec le futur simple"), ("❓", "faire une hypothèse : si + présent, futur"), ("🗺️", "planifier un trajet et une excursion")],
            ["Comment tu viens à l'école ?", "Tu as déjà pris le train en Belgique ?", "Qu'est-ce que tu fais si ton bus est en retard ?"],
            ["le train", "le bus", "la gare", "le billet", "l'horaire", "le quai", "le retard", "la correspondance", "partir", "arriver"], TINT)

    # ---------- Découvrir ----------
    bd = '<div class="grid2" style="gap:3mm">' + "".join([
        bd_case(1, lr("amina", ["Samedi, j'irai à Bruxelles avec ma sœur. Nous prendrons le train de 9 h 15."], "fatou", ["Tu achèteras ton billet au guichet ?"], "rire", "pense")),
        bd_case(2, lr("amina", ["Non, au distributeur ou sur l'application : c'est plus rapide."], extra='<div class="c" style="font-size:22pt">🏧📱🎫</div>')),
        bd_case(3, lr("amina", ["Samedi matin, à la gare… Oh non ! Le train de 9 h 15 a 20 minutes de retard !"], extra=f'<div class="c" style="font-size:20pt">🪧 ⏳ +20</div>', ma="surpris")),
        bd_case(4, lr("yonas", ["Ne t'inquiète pas ! Si tu prends le train de 9 h 32, tu arriveras presque à la même heure."], "amina", ["Super ! Merci, Yonas !"], "sourire", "rire")),
        bd_case(5, '<div class="bubble" style="margin-top:6mm;font-size:11pt">📢 « Le train de 9 h 32 à destination de Bruxelles-Midi partira de la voie 4. »</div><div class="c" style="font-size:24pt;margin-top:3mm">🛤️4️⃣🚆</div>'),
        bd_case(6, lr("amina", ["Ouf ! Si tout va bien, nous serons à Bruxelles à 10 h 30. On visitera l'Atomium !"], extra='<div class="c" style="font-size:22pt">⚛️😄</div>', ma="rire")),
    ]) + '</div>'
    e = E("J'écoute et je lis la BD : Amina part à Bruxelles.", bd, ["ecoute", "lis"], 1, "A",
          script="Lire deux fois, imiter l'annonce en gare (voix neutre, lente). Faire repérer les verbes au futur : j'irai, nous prendrons, tu achèteras, tu arriveras, partira, nous serons, on visitera ; et la phrase avec si : Si tu prends…, tu arriveras…", sol="Activité orale.")
    b.page(f'<h2>Découvrir · Un samedi à Bruxelles</h2>{e}', "Découvrir")
    e = E("Je réponds par une phrase complète.", f"<p>1. Où Amina ira-t-elle samedi ? Avec qui ? {blank('xl')}</p><p>2. Où achètera-t-elle son billet ? Pourquoi ? {blank('xl')}</p><p>3. Quel est le problème à la gare ? {blank('xl')}</p><p>4. Quelle solution Yonas propose-t-il ? {blank('xl')}</p><p>5. De quelle voie part le train de 9 h 32 ? {blank()} Qu'est-ce qu'Amina visitera ? {blank('l')}</p>",
          ["lis", "ecris"], 1, "B", sol="1. à Bruxelles, avec sa sœur — 2. au distributeur ou sur l'application, c'est plus rapide — 3. Le train de 9 h 15 a 20 minutes de retard. — 4. prendre le train de 9 h 32 — 5. la voie 4 · l'Atomium")
    e2 = E("Je souligne les verbes au futur dans la BD et j'écris leur infinitif.", table(["Verbe au futur", "Infinitif"], [["j'irai", "aller"], ["", ""], ["", ""], ["", ""], ["", ""], ["", ""]], ["91mm", "91mm"]).replace("<td></td>", '<td style="height:7mm"></td>'), ["lis", "souligne", "ecris"], 2, "B",
           sol="nous prendrons → prendre · tu achèteras → acheter · tu arriveras → arriver · partira → partir · nous serons → être · on visitera → visiter")
    b.page(f'{e}{e2}', "Découvrir")
    msg = '''<div class='card' style='background:#F4FAF9;line-height:1.6'><p><b>📧 De :</b> Mme Lambert · <b>À :</b> parents et élèves du DASPA · <b>Objet :</b> excursion du jeudi 12 juin</p>
<p>Chers parents, chers élèves,</p><p>Le jeudi 12 juin, la classe partira en excursion à Liège. Nous nous retrouverons à 8 h 15 devant la gare de Namur. Le train partira à 8 h 37 et arrivera à Liège-Guillemins à 9 h 25. Le matin, nous visiterons un musée ; à midi, nous pique-niquerons dans un parc. L'après-midi, nous monterons l'escalier de la Montagne de Bueren (374 marches !).</p>
<p>Le retour est prévu à 16 h 33 ; nous serons à Namur à 17 h 20. S'il pleut, nous visiterons un deuxième musée à la place du parc. Chaque élève devra apporter son pique-nique, une bouteille d'eau et sa carte d'identité. Si votre enfant a un problème de santé, merci de me prévenir.</p><p>Bien cordialement,<br>Claire Lambert</p></div>'''
    e = E("Je lis le courriel de Mme Lambert. Je réponds.", msg + f"<p class='mt2'>1. Où et quand la classe partira-t-elle ? {blank('xl')}</p><p>2. À quelle heure et où les élèves doivent-ils être le matin ? {blank('xl')}</p><p>3. Combien de temps dure le trajet en train ? {blank()}</p><p>4. Que fera la classe s'il pleut ? {blank('xl')}</p><p>5. Que faut-il apporter ? {blank('xl')}</p>", ["lis", "ecris"], 2, "B",
          sol="1. à Liège, le jeudi 12 juin — 2. à 8 h 15, devant la gare de Namur — 3. 48 minutes (8 h 37 → 9 h 25) — 4. Elle visitera un deuxième musée à la place du parc. — 5. un pique-nique, une bouteille d'eau, la carte d'identité")
    b.page(f'<h2>Découvrir · L\'excursion de la classe</h2>{e}', "Découvrir")

    # ---------- Lexique ----------
    e = E("Les moyens de transport. J'écoute et je répète.", emogrid(TRANSP, 6), ["ecoute", "repete"], 1, "A",
          script="Lire chaque mot avec la préposition : en train, en bus, en tram, en métro, en voiture, en avion, en taxi, en bateau, en car ; mais à vélo, à trottinette, à pied. Demander : « Comment tu viens à l'école ? »", sol="Activité orale.")
    e2 = E("En ou à ? Je complète.", "<p>1. Je vais à l'école ___ bus. 2. Mon frère va au travail ___ vélo. 3. Nous partons au Maroc ___ avion. 4. Bilal vient ___ pied. 5. À Bruxelles, je circule ___ métro. 6. On fait le tour du lac ___ bateau.</p><div class='astuce'>On est <b>dans</b> le véhicule → <b>en</b> (en train, en voiture). On est <b>sur</b> le véhicule ou on marche → <b>à</b> (à vélo, à cheval, à pied).</div>", ["complete"], 1, "C",
           sol="1. en — 2. à — 3. en — 4. à — 5. en — 6. en")
    b.page(f'<h2>Les mots du voyage · les transports</h2>{e}{e2}', "Lexique")
    e = E("À la gare. J'écoute et je répète.", emogrid(GARE, 6), ["ecoute", "repete"], 1, "A",
          script="Lire chaque mot. Expliquer : le quai = l'endroit où on attend ; la voie = les rails (on dit « le train part de la voie 4 »). Une correspondance = changer de train ou de bus pendant le voyage.", sol="Activité orale.")
    e2 = E("Je relie le mot et sa définition.", relie(["la correspondance", "le guichet", "le quai", "le contrôleur", "un aller-retour", "supprimé"], ["l'endroit où on attend le train", "le billet pour aller et revenir", "la personne qui vérifie les billets", "le train ne roule pas", "changer de train pendant le voyage", "l'endroit où une personne vend les billets"]), ["relie"], 1, "B",
           sol="correspondance → changer de train · guichet → personne qui vend · quai → attendre · contrôleur → vérifie · aller-retour → aller et revenir · supprimé → ne roule pas")
    b.page(f'<h2>Les mots du voyage · à la gare</h2>{e}{e2}', "Lexique")
    verbs = [("🚶‍♀️", "partir ≠ arriver"), ("⬆️", "monter dans ≠ descendre de"), ("🔄", "changer de train"), ("⏳", "attendre"), ("✅", "composter, valider (bus, tram)"), ("🏃", "rater, manquer le train"), ("🔁", "faire un aller-retour"), ("📍", "réserver")]
    e = E("Les verbes du voyage. Je lis et je mime.", "<div class='grid4'>" + "".join(f"<div class='card c' style='padding:2mm'><span class='emo s'>{em}</span><b class='sm'>{t}</b></div>" for em, t in verbs) + "</div>", ["lis", "repete"], 1, "A", script="Mimer chaque verbe ; un élève mime, les autres disent le verbe.", sol="Activité orale.")
    e2 = E("Je complète le récit avec les verbes du voyage au passé composé.", "<p>Hier, j'______________ (rater) le bus de 7 h 40. J'______________ (attendre) le suivant pendant 15 minutes. Je ______________ (monter) dans le bus et j'______________ (valider) ma carte. À la gare, je ______________ (descendre) et je ______________ (changer) de bus. Finalement, je ______________ (arriver) à l'école à 8 h 30.</p>", ["complete"], 2, "C",
           sol="ai raté · ai attendu · suis monté(e) · ai validé · suis descendu(e) · ai changé · suis arrivé(e)")
    b.page(f'<h2>Les mots du voyage · les verbes</h2>{e}{e2}', "Lexique")
    bel = table(["En Belgique, on dit…", "Ça veut dire…", "Exemple"], [["un <b>ticket</b> (de train, de bus)", "un billet", "J'ai acheté mon ticket sur l'appli."], ["un / une <b>navetteur</b>, <b>navetteuse</b>", "une personne qui fait chaque jour le trajet maison – travail", "Le matin, le train est plein de navetteurs."], ["<b>tirer son plan</b>", "se débrouiller seul(e)", "Si le bus est supprimé, je tirerai mon plan !"], ["<b>à tantôt</b>", "à tout à l'heure (plus tard dans la journée)", "Je pars à la gare, à tantôt !"], ["<b>le tram</b>, <b>l'arrêt de tram</b>", "(comme en France)", "Je descends à l'arrêt de tram « Gare »."]], ["50mm", "62mm", "70mm"])
    e = E("Je lis les belgicismes. Je réécris les phrases en français standard.", bel + "<p class='mt2'>1. N'oublie pas ton ticket ! → ______________________________</p><p>2. Ne t'inquiète pas pour moi, je tire mon plan. → ______________________________</p><p>3. Je vais au guichet, à tantôt ! → ______________________________</p>", ["lis", "ecris"], 2, "B",
          sol="1. N'oublie pas ton billet ! — 2. … je me débrouille. — 3. … à tout à l'heure !")
    e2 = E("Les sociétés de transport en Belgique. Je lis et je complète.", "<div class='astuce' style='margin-top:0'>Les trains belges sont gérés par la <b>SNCB</b>. En Wallonie, les bus (et le métro léger de Charleroi) sont gérés par le <b>TEC</b> ; à Bruxelles, par la <b>STIB</b> (métro, tram, bus) ; en Flandre, par <b>De Lijn</b>. Les enfants de moins de 12 ans voyagent gratuitement en train (conditions sur le site de la SNCB).</div><p>1. Je prends le bus à Charleroi : c'est le ______ . 2. Je prends le métro à Bruxelles : c'est la ______ . 3. Je prends le train : c'est la ______ . 4. Mon petit frère a 9 ans : en train, il paie ______________ .</p>", ["lis", "complete"], 1, "B",
           sol="1. TEC — 2. STIB — 3. SNCB — 4. rien (il voyage gratuitement, avec les conditions de la SNCB)")
    b.page(f'<h2>🇧🇪 Les mots d\'ici · se déplacer en Belgique</h2>{e}{e2}', "Lexique")

    # ---------- Leçon 1 : futur simple ----------
    l1 = lecon("Le futur simple : la formation", '''<div class='grid2'><div class='card' style='background:#fff'><b>La recette</b><p>infinitif + <b>-ai, -as, -a, -ons, -ez, -ont</b><br>(les terminaisons ressemblent au verbe <b>avoir</b> !)<br>Verbes en <b>-re</b> : on enlève le <b>e</b> : prendre → je prendr<b>ai</b>.</p>'''
               + table(["PARTIR", ""], [["je partir<b>ai</b>", "nous partir<b>ons</b>"], ["tu partir<b>as</b>", "vous partir<b>ez</b>"], ["il / elle / on partir<b>a</b>", "ils / elles partir<b>ont</b>"]], ["38mm", "38mm"]) + '''</div>
<div class='card' style='background:#fff'><b>Les verbes irréguliers (radical spécial)</b><p class='sm' style='line-height:1.7'>être → je <b>ser</b>ai · avoir → j'<b>aur</b>ai<br>aller → j'<b>ir</b>ai · faire → je <b>fer</b>ai<br>venir → je <b>viendr</b>ai · voir → je <b>verr</b>ai<br>pouvoir → je <b>pourr</b>ai · vouloir → je <b>voudr</b>ai<br>devoir → je <b>devr</b>ai · savoir → je <b>saur</b>ai<br>falloir → il <b>faudr</b>a · pleuvoir → il <b>pleuvr</b>a</p><p class='xs'>acheter → j'ach<b>è</b>terai · appeler → j'appe<b>ll</b>erai</p></div></div>
<p class='sm mt2'>On entend toujours le son <b>[ʁ]</b> avant la terminaison : je partirai, je serai, j'irai.</p>''')
    e = E("Je conjugue au futur simple.", "<p>1. Demain, je (prendre) ______________ le train. 2. Nous (arriver) ______________ à 10 h. 3. Tu (être) ______________ à la gare ? 4. Les élèves (aller) ______________ à Liège. 5. Vous (avoir) ______________ un billet. 6. Il (faire) ______________ beau samedi. 7. On (voir) ______________ la mer ! 8. Je (pouvoir) ______________ venir.</p>", ["complete"], 1, "C",
          sol="1. prendrai — 2. arriverons — 3. seras — 4. iront — 5. aurez — 6. fera — 7. verra — 8. pourrai")
    b.page(f'{l1}{e}', "Leçon 1")
    e = E("Je complète le tableau.", table(["Infinitif", "je", "nous", "ils"], [["visiter", "je visiterai", "", ""], ["partir", "", "", ""], ["prendre", "", "", ""], ["être", "", "", ""], ["aller", "", "", ""], ["venir", "", "", ""]], ["40mm", "48mm", "48mm", "46mm"]).replace("<td></td>", '<td style="height:7mm"></td>'), ["ecris"], 2, "C",
          sol="visiterons, visiteront · partirai, partirons, partiront · prendrai, prendrons, prendront · serai, serons, seront · irai, irons, iront · viendrai, viendrons, viendront")
    e2 = E("J'écoute : présent, futur proche ou futur simple ? Je coche.", checks(8, ["présent", "futur proche", "futur simple"]), ["ecoute", "coche"], 2, "A",
           script="1. Je pars à 8 heures. — 2. Je partirai à 8 heures. — 3. Je vais partir à 8 heures. — 4. Nous prendrons le bus. — 5. Nous prenons le bus. — 6. Ils vont arriver. — 7. Ils arriveront. — 8. Tu seras là ?",
           sol="1. présent — 2. futur simple — 3. futur proche — 4. futur simple — 5. présent — 6. futur proche — 7. futur simple — 8. futur simple")
    e3 = E("Défi ! Je trouve et je corrige les 4 erreurs.", "<div class='card big'>Demain, je irai à la gare. Je prenderai le train de 9 h. Nous arriverons à 10 h et nous visitons le musée. Il fera beau, j'espère ! Mes amis vienneront avec moi.</div>" + lines(1), ["barre", "ecris"], 3, "C",
           sol="j'irai · je prendrai · nous visiterons · viendront")
    b.page(f'{e}{e2}{e3}', "S'entraîner")

    # ---------- Leçon 2 : emplois du futur ----------
    l2 = lecon("Le futur simple : quand je l'utilise", table(["Pour…", "Exemple"], [["📅 parler d'un projet, d'un programme", "Le jeudi 12 juin, la classe <b>partira</b> à Liège."], ["🔮 faire une prévision (météo, avenir)", "Demain, il <b>pleuvra</b> sur les Ardennes. Plus tard, je <b>serai</b> infirmière."], ["🤝 faire une promesse", "Je t'<b>appellerai</b> en arrivant, promis !"], ["📢 une annonce officielle", "Le train <b>partira</b> de la voie 4. Il <b>s'arrêtera</b> à Namur."], ["✅ une consigne pour plus tard", "Vous <b>apporterez</b> votre carte d'identité."]], ["70mm", "112mm"]) +
               '<div class="astuce" style="margin:2mm 0 0"><b>Futur proche ou futur simple ?</b> Le futur proche (je <b>vais partir</b>) : c\'est bientôt, c\'est sûr, souvent à l\'oral. Le futur simple (je <b>partirai</b>) : plus lointain, plus formel, très utilisé à l\'écrit (programmes, courriers, annonces).</div>'
               '<p class="sm"><b>Mots du futur :</b> demain · après-demain · la semaine prochaine · le mois prochain · dans deux jours · bientôt · plus tard · un jour · en 2030</p>')
    e = E("Je transforme le futur proche en futur simple.", "<p>1. Je vais téléphoner à mon oncle. → ______________________________</p><p>2. Nous allons visiter Bruges. → ______________________________</p><p>3. Il va pleuvoir demain. → ______________________________</p><p>4. Vous allez faire une excursion. → ______________________________</p>", ["ecris"], 1, "C",
          sol="1. Je téléphonerai à mon oncle. — 2. Nous visiterons Bruges. — 3. Il pleuvra demain. — 4. Vous ferez une excursion.")
    b.page(f'{l2}{e}', "Leçon 2")
    meteo = "<div class='grid4'>" + "".join(f"<div class='card c' style='padding:2mm'><b>{v}</b><div style='font-size:22pt'>{em}</div><span class='xs'>{t}</span></div>" for v, em, t in [("Mer du Nord", "🌬️☁️", "vent fort, 12 °C"), ("Bruxelles", "🌦️", "averses, 14 °C"), ("Namur", "⛅", "éclaircies, 15 °C"), ("Ardennes", "🌧️", "pluie, 11 °C")]) + "</div>"
    e = E("Je lis la carte météo de demain et j'écris le bulletin au futur (4 phrases).", meteo + lines(3), ["lis", "ecris"], 2, "C",
          sol="Ex. : Demain, à la côte, le vent soufflera fort et il fera 12 °C. À Bruxelles, il y aura des averses. À Namur, il y aura des éclaircies. Dans les Ardennes, il pleuvra.")
    e2 = E("Mon programme de la semaine prochaine : j'écris 5 phrases au futur simple (école, sport, famille, sortie…).", lines(4), ["ecris"], 2, "C", sol="Futur simple correct, marqueurs de temps.")
    e4 = E("Les promesses : ton ami part en vacances. Tu lui fais 3 promesses au futur simple.", "<p class='sm'>Ex. : Je t'écrirai tous les jours. Je donnerai à manger à ton chat.</p>" + lines(2), ["ecris"], 1, "C", sol="Promesses au futur (écrirai, téléphonerai, garderai…).")
    e3 = E("Jeu de la voyante : en duo, je lis l'avenir de mon voisin dans sa main (pour rire !) : « Dans dix ans, tu habiteras… tu seras… tu auras… » Il répond : « Super ! / Oh non ! »", "", ["parle", "duo", "joue"], 1, "A", sol="Prédictions au futur simple.")
    b.page(f'{e}{e2}{e4}{e3}', "S'entraîner")

    # ---------- Leçon 3 : si + présent, futur ----------
    l3 = lecon("Faire une hypothèse : si + présent → futur", '''<p class='big c'><b>Si</b> + présent, … futur simple (ou impératif)</p>
<div class='grid2'><div class='card' style='background:#fff'><p><b>Si</b> le train <b>est</b> en retard, je <b>prendrai</b> le bus.<br><b>S'</b>il <b>pleut</b>, nous <b>visiterons</b> un musée.<br><b>Si</b> tu <b>rates</b> le train, <b>appelle</b>-moi !</p></div>
<div class='card' style='background:#fff'><p>On peut inverser :<br>Je <b>prendrai</b> le bus <b>si</b> le train <b>est</b> en retard.<br>(pas de virgule quand « si » est au milieu)</p></div></div>
<div class='attention' style='margin:2mm 0 0'>⚠️ <b>Jamais de futur après si</b> : « Si il pleuvra » ✗ → <b>S'il pleut</b> ✓.<br>si + il / ils → <b>s'</b>il, <b>s'</b>ils (mais : si elle, si on, si tu).</div>''')
    e = E("Je relie le début et la fin de la phrase.", relie(["Si le train est supprimé,", "S'il fait beau,", "Si tu as moins de 12 ans,", "Si nous partons à 8 h,", "Si tu te perds dans la gare,"], ["tu voyageras gratuitement en train.", "demande à un agent de la gare.", "nous arriverons avant midi.", "je prendrai le suivant.", "on pique-niquera dans le parc."]), ["relie"], 1, "B",
          sol="supprimé → je prendrai le suivant · beau → pique-niquera · moins de 12 ans → gratuitement · 8 h → avant midi · perds → demande à un agent de la gare")
    e2 = E("Je souligne le verbe au présent (après si) et j'entoure le verbe au futur.", "<div class='card big' style='line-height:1.9'>1. Si tu as faim, nous mangerons une gaufre.<br>2. Je t'attendrai à la gare si ton train arrive avant midi.<br>3. S'il fait froid, vous prendrez un manteau.</div>", ["souligne", "entoure"], 1, "B",
           sol="Présent : as, arrive, fait · Futur : mangerons, attendrai, prendrez")
    b.page(f'{l3}{e}{e2}', "Leçon 3")
    e = E("Je conjugue : présent après si, futur dans l'autre partie.", "<p>1. Si tu (venir) ______________ avec moi, nous (visiter) ______________ l'Atomium. 2. S'il (y avoir) ______________ grève, je (rester) ______________ à la maison. 3. Si vous (arriver) ______________ en retard, le train (partir) ______________ sans vous ! 4. Si je (réussir) ______________ mon examen, je (aller) ______________ à la mer.</p>", ["complete"], 2, "C",
          sol="1. viens · visiterons — 2. y a · resterai — 3. arrivez · partira — 4. réussis · irai")
    e2 = E("Je termine les phrases avec mes idées.", "<p>1. Si je rate mon bus, ______________________________</p><p>2. S'il neige demain, ______________________________</p><p>3. Si j'ai de l'argent cet été, ______________________________</p><p>4. Si mon train est supprimé, ______________________________</p>", ["ecris"], 2, "C", sol="Ex. : 1. j'attendrai le suivant / je préviendrai l'école. — 2. on fera un bonhomme de neige. — 3. je voyagerai en Espagne. — 4. je prendrai le bus.")
    e3 = E("La chaîne des « si » : en groupe, chacun reprend la fin de la phrase du voisin. « Si je vais à la mer, je mangerai une glace. — Si je mange une glace, j'aurai mal au ventre. — Si j'ai mal au ventre… »", "", ["parle", "groupe", "joue"], 2, "A", sol="Chaîne d'hypothèses (si + présent → futur).")
    b.page(f'{e}{e2}{e3}', "S'entraîner")

    # ---------- Leçon 4 : acheter un billet ----------
    l4 = lecon("Acheter un billet, demander une information", table(["Le / la voyageur(se)", "L'employé(e) au guichet"], [
        ["Bonjour, un aller simple pour Liège, s'il vous plaît.", "Pour aujourd'hui ? Vous avez moins de 26 ans ?"],
        ["Un aller-retour pour Bruxelles, retour ce soir.", "En semaine ou le week-end ? Ça fait … euros."],
        ["À quelle heure part le prochain train pour Mons ?", "À 10 h 12, voie 3. Il faut changer à Charleroi."],
        ["Le train est direct ? / Il faut changer ?", "Non, il y a une correspondance à Bruxelles-Midi."],
        ["Il arrive à quelle heure ?", "Il arrive à 11 h 05."],
        ["Je peux payer par carte ?", "Oui, bien sûr. Voici votre billet. Bon voyage !"]], ["91mm", "91mm"]) +
        '<p class="sm mt2"><b>Mots utiles :</b> un aller simple · un aller-retour · en 1<sup>re</sup> / 2<sup>e</sup> classe · direct · avec correspondance · le prochain / le dernier train · réduction (jeune, famille) · <b>à destination de</b> / <b>en provenance de</b></p>'
        '<div class="astuce" style="margin:1mm 0 0">Acheter son billet <b>avant</b> de monter (distributeur, guichet, application) : à bord, le billet coûte souvent plus cher. Dans le bus, on <b>valide</b> sa carte ou son ticket en montant.</div>')
    e = E("Je complète le dialogue au guichet.", "<div class='card'><p>— Bonjour, je voudrais un ______________ pour Namur, s'il vous plaît. Je reviens ce soir.<br>— Vous avez ______________ 26 ans ?<br>— Oui, j'ai 16 ans.<br>— Le train est à 14 h 20, ______________ 2.<br>— Il est ______________ ou il faut changer ?<br>— Il est direct. Il ______________ à Namur à 15 h 05.<br>— Merci, ______________ !</p></div>", ["complete"], 1, "C",
          sol="aller-retour · moins de · voie · direct · arrive · au revoir / bonne journée")
    b.page(f'{l4}{e}', "Leçon 4")
    dist = "<div class='doc' style='transform:none;background:#EAF4F3;border:2px solid #1D7874;border-radius:3mm;padding:3mm;max-width:120mm;margin:0 auto'><div class='c' style='background:#1D7874;color:#fff;border-radius:2mm;padding:1.5mm;font-weight:700'>🏧 DISTRIBUTEUR · Acheter un billet</div>" + "".join(f"<div class='card sm' style='margin-top:1.5mm;padding:1.5mm 3mm'><b>{i}.</b> {t}</div>" for i, t in enumerate(["Choisissez votre gare d'arrivée", "Aller simple ▢ · Aller-retour ▢", "Date du voyage : aujourd'hui ▢ · autre date ▢", "Voyageurs : adulte ▢ · moins de 26 ans ▢ · enfant de moins de 12 ans ▢", "Classe : 1re ▢ · 2e ▢", "Payez : carte bancaire ▢ · application de paiement ▢", "Prenez votre billet et votre reçu"], 1)) + "<p class='xs muted c' style='margin:1mm 0 0'>Écran fictif simplifié</p></div>"
    e = E("Je lis l'écran du distributeur. Je coche ce que je choisis pour la situation, puis je numérote les étapes dans l'ordre où je les fais.", dist + "<p class='mt2'><b>Situation :</b> Tu as 16 ans. Tu vas à Mons aujourd'hui et tu reviens ce soir, en 2e classe. Tu paies par carte.</p>", ["lis", "coche"], 2, "B",
          sol="Mons · aller-retour · aujourd'hui · moins de 26 ans · 2e classe · carte bancaire ; étapes 1 → 7 dans l'ordre de l'écran")
    e2 = E("J'écoute 3 dialogues au guichet. Je complète le tableau.", table(["", "Destination", "Aller simple / aller-retour", "Heure du train", "Voie", "Direct ?"], [["1", "", "", "", "", ""], ["2", "", "", "", "", ""], ["3", "", "", "", "", ""]], ["10mm", "36mm", "42mm", "32mm", "22mm", "40mm"]).replace("<td></td>", '<td style="height:8mm"></td>'), ["ecoute", "ecris"], 2, "A",
           script="1. — Un aller simple pour Liège, s'il vous plaît. — Le prochain train part à 10 h 37, voie 2. Il est direct. — 2. — Un aller-retour pour Arlon, s'il vous plaît. — Le train de 11 h 05, voie 5. Vous changez à Namur. — 3. — Un aller-retour pour Bruges, pour deux personnes. — Le train part à 9 h 52, voie 1 ; il faut changer à Bruxelles-Midi.",
           sol="1. Liège · aller simple · 10 h 37 · 2 · oui — 2. Arlon · aller-retour · 11 h 05 · 5 · non, changer à Namur — 3. Bruges · aller-retour (2 personnes) · 9 h 52 · 1 · non, changer à Bruxelles-Midi")
    e3 = E("J'écris le dialogue au guichet pour la situation : tu vas à Arlon avec ta mère, aller simple, demain matin. Tu demandes l'heure, la voie et s'il faut changer.", lines(4), ["ecris"], 2, "C", sol="Dialogue complet : salutation, demande, informations, remerciement.")
    b.page(f'{e}{e2}{e3}', "S'entraîner")

    # ---------- Leçon 5 : retards, annonces ----------
    l5 = lecon("Comprendre une annonce · gérer un retard", table(["L'annonce dit…", "Ça veut dire…"], [["Le train à destination de… <b>est annoncé avec un retard de</b> 15 minutes.", "Il arrivera / partira 15 minutes plus tard."], ["Le train… <b>est supprimé</b>.", "Il ne roule pas aujourd'hui."], ["<b>Changement de voie</b> : le train partira de la voie 7.", "Il faut aller sur un autre quai."], ["<b>Prochain arrêt</b> : Namur. Correspondance pour…", "La prochaine gare est Namur. On peut y changer de train."], ["<b>Attention à la marche</b> en descendant du train.", "Il y a un espace entre le train et le quai."], ["<b>Éloignez-vous de la bordure du quai</b>.", "Ne restez pas trop près des rails : un train arrive."]], ["100mm", "82mm"]) +
               '<p class="sm mt2"><b>Réagir et s\'informer :</b> Excusez-moi, le train pour Mons a du retard ? · Il y a un autre train ? · Quelle est la solution ? · Je vais rater ma correspondance ! · Je préviens l\'école : « Bonjour, je serai en retard parce que mon train est supprimé. »</p>')
    e = E("Que fais-tu ? Je relie l'annonce et l'action.", relie(["« Changement de voie : voie 7. »", "« Le train est supprimé. »", "« Prochain arrêt : Namur. »", "« Éloignez-vous de la bordure du quai. »"], ["Je recule.", "Je me prépare à descendre (si je vais à Namur).", "Je vais vite au quai 7.", "Je cherche un autre train ou un bus."]), ["lis", "relie"], 1, "B",
          sol="changement de voie → quai 7 · supprimé → autre train ou bus · prochain arrêt → se préparer · bordure → reculer")
    b.page(f'{l5}{e}', "Leçon 5")
    e = E("J'écoute les annonces en gare. Je coche la bonne information.", "".join(f"<p style='margin:1.5mm 0'><b>{i}.</b> " + " &nbsp; ".join(f"<span class='chk'></span>{o}" for o in opts) + "</p>" for i, opts in enumerate([["retard 10 min", "retard 20 min", "supprimé"], ["voie 3", "voie 8", "voie 13"], ["direct", "correspondance à Namur", "correspondance à Liège"], ["à l'heure", "supprimé", "changement de voie"]], 1)), ["ecoute", "coche"], 2, "A",
           script="1. « Le train de 10 h 12 à destination d'Ostende est annoncé avec un retard d'environ 20 minutes. » — 2. « Attention, changement de voie : le train à destination de Charleroi partira de la voie 8. » — 3. « Le train à destination de Luxembourg. Correspondance à Namur pour Dinant. » — 4. « Nous vous informons que le train de 11 h 04 à destination de Mons est supprimé. Nous vous prions de nous excuser pour ce désagrément. »",
           sol="1. retard 20 min — 2. voie 8 — 3. correspondance à Namur — 4. supprimé")
    e2 = E("Ton train est supprimé. Tu écris un message à l'école pour prévenir (4 lignes) : qui, quel problème, ta solution, l'heure d'arrivée (futur).", lines(4), ["ecris"], 2, "C",
           sol="Ex. : Bonjour Madame, c'est Bilal. Mon train de 7 h 40 est supprimé. Je prendrai le bus de 8 h 05. J'arriverai à l'école vers 8 h 50. Excusez-moi. Bilal")
    e3 = E("Jeu de rôle : je suis voyageur, mon voisin est agent à la gare. Je lui explique mon problème (retard, train supprimé, correspondance ratée) et je demande une solution. On change.", "<div class='grid3'>" + "".join(f"<div class='card c sm' style='border-style:dashed'>{t}</div>" for t in ["⏳ Retard de 30 min : tu vas rater ta correspondance pour Arlon.", "❌ Train supprimé : tu dois être à Mons à 14 h.", "🧳 Tu as oublié ton sac dans le train."]) + "</div>", ["parle", "duo", "joue"], 2, "A",
           sol="Expliquer, demander, comprendre la solution, remercier.")
    b.page(f'{e}{e2}{e3}', "S'entraîner")

    # ---------- FLSco : lire un horaire ----------
    l6 = lecon("Lire un horaire complexe (méthode)", '''<p>Un horaire est un <b>tableau à double entrée</b> : les <b>lignes</b> = les gares (ou les arrêts), les <b>colonnes</b> = les trains (ou les bus). Pour trouver une information :</p>
<p>1️⃣ Je repère la <b>gare de départ</b> et la <b>gare d'arrivée</b> dans la première colonne. &nbsp; 2️⃣ Je choisis la <b>colonne</b> du train (heure de départ). &nbsp; 3️⃣ Je descends dans la colonne jusqu'à ma gare d'arrivée. &nbsp; 4️⃣ Je lis les <b>notes</b> (symboles, lettres) en bas : jours de circulation, correspondances. &nbsp; 5️⃣ Je <b>calcule la durée</b> : heure d'arrivée − heure de départ.</p>
<p class='sm'><b>Symboles fréquents :</b> | ou — = le train ne s'arrête pas · ⓐ = note à lire en bas · « en semaine » = du lundi au vendredi · « sauf jours fériés » · IC = InterCity (peu d'arrêts) · L = train local (tous les arrêts)</p>''')
    hor = table(["Train", "IC 1", "L 2", "IC 3 ⓐ", "L 4", "IC 5"], [["<b>Namur</b> (départ)", "07:37", "07:52", "08:37", "08:52", "09:37"], ["Flawinne", "|", "07:58", "|", "08:58", "|"], ["Tamines", "07:49", "08:07", "08:49", "09:07", "09:49"], ["Charleroi-Central", "08:00", "08:21", "09:00", "09:21", "10:00"], ["Luttre", "|", "08:33", "|", "09:33", "|"], ["Nivelles", "08:17", "08:45", "|", "09:45", "10:17"], ["<b>Bruxelles-Midi</b> (arrivée)", "08:40", "09:20", "09:28", "10:20", "10:40"]], ["52mm", "26mm", "26mm", "26mm", "26mm", "26mm"])
    e = E("Je lis l'horaire « Namur → Bruxelles-Midi » (horaire fictif simplifié). Je réponds.", hor + "<p class='xs'>ⓐ circule seulement en semaine, sauf jours fériés · | = le train ne s'arrête pas dans cette gare</p>" + f"<p>1. Combien de trains partent de Namur entre 7 h 30 et 9 h 00 ? {blank()}</p><p>2. Le train IC 3 s'arrête-t-il à Nivelles ? {blank()} Circule-t-il le samedi ? {blank()}</p><p>3. Je dois être à Bruxelles-Midi avant 9 h 30. Quel train je prends au plus tard ? {blank()}</p>", ["lis", "ecris"], 2, "B",
          sol="1. quatre (07:37, 07:52, 08:37, 08:52) — 2. non (|) ; non (seulement en semaine) — 3. l'IC 3 de 08:37 (arrivée 09:28) en semaine ; le samedi : le L 2 de 07:52 (arrivée 09:20)")
    b.page(f'<span class="tag-doc">🎒 FRANÇAIS DE L\'ÉCOLE</span>{l6}{e}', "Consignes & école")
    e = E("Je calcule des durées avec l'horaire.", table(["Trajet", "Départ", "Arrivée", "Durée"], [["IC 1 Namur → Bruxelles-Midi", "07:37", "08:40", ""], ["L 2 Namur → Bruxelles-Midi", "07:52", "09:20", ""], ["L 4 Tamines → Nivelles", "", "", ""], ["IC 5 Charleroi → Bruxelles-Midi", "", "", ""]], ["70mm", "36mm", "36mm", "40mm"]).replace("<td></td>", '<td style="height:8mm"></td>') + "<p class='xs muted'>Méthode : je compte jusqu'à l'heure pile, puis j'ajoute les minutes. 07:37 → 08:00 = 23 min ; 08:00 → 08:40 = 40 min ; total = 1 h 03.</p>", ["ecris"], 2, "C",
          sol="1 h 03 · 1 h 28 · 09:07 → 09:45 = 38 min · 10:00 → 10:40 = 40 min")
    e2 = E("Pourquoi le train L est-il plus lent que l'IC ? J'explique avec l'horaire (2 phrases, avec « parce que »).", lines(2), ["ecris"], 2, "C", sol="Le train L est plus lent parce qu'il s'arrête dans toutes les gares (Flawinne, Luttre…). L'IC s'arrête moins souvent, donc il arrive plus vite.")
    e3 = E("Défi ! Je fais une phrase « si » avec l'horaire : Si je rate l'IC de 8 h 37, …", lines(1), ["ecris"], 3, "C", sol="Ex. : Si je rate l'IC de 8 h 37, je prendrai le train L de 8 h 52 et j'arriverai à Bruxelles-Midi à 10 h 20.")
    e4 = E("Mon horaire : j'écris l'horaire de mon trajet maison → école (arrêts ou étapes, heures).", table(["Étape / arrêt", "Heure"], [["Départ de la maison", ""], ["", ""], ["", ""], ["Arrivée à l'école", ""]], ["130mm", "52mm"]).replace("<td></td>", '<td style="height:7mm"></td>'), ["ecris"], 1, "C", sol="Horaire personnel cohérent.")
    b.page(f'{e}{e2}{e3}{e4}', "Consignes & école")

    # ---------- Documents de la vie ----------
    bil = f"""<div class='doc' style='transform:rotate(-.8deg);border:1.5px solid #9aa1b1;max-width:150mm;margin:0 auto;font-family:monospace;font-size:10pt'><div style='background:{MC};color:#fff;padding:1.5mm 3mm;display:flex;justify-content:space-between'><b>BILLET · TICKET</b><span>2e classe</span></div>
<div style='padding:2.5mm 3mm;display:grid;grid-template-columns:1fr 1fr;gap:1mm 6mm'><span>De : <b>NAMUR</b></span><span>À : <b>LIÈGE-GUILLEMINS</b></span><span>Aller-retour</span><span>1 voyageur · moins de 26 ans</span><span>Valable le : 12/06</span><span>Prix : 9,40 €</span><span class='xs'>Valable sur tous les trains du jour, via le trajet le plus court.</span><span class='xs'>Billet personnel · présentez-le au contrôle avec votre carte d'identité.</span></div><div class='xs c muted'>Billet fictif à usage pédagogique</div></div>"""
    e = E("Je lis le billet. Je réponds.", bil + f"<p class='mt2'>1. D'où part le voyageur ? Où va-t-il ? {blank('xl')}</p><p>2. Peut-il revenir avec ce billet ? Comment je le sais ? {blank('xl')}</p><p>3. Il peut voyager le 13/06 ? {blank()}</p><p>4. Que doit-il montrer au contrôleur ? {blank('l')}</p><p>5. La classe (14 élèves) achète ce billet : combien paie-t-elle en tout ? {blank()}</p>", ["lis", "ecris"], 2, "B",
          sol="1. de Namur, à Liège-Guillemins — 2. oui : « aller-retour » — 3. non (valable le 12/06) — 4. le billet et sa carte d'identité — 5. 14 × 9,40 = 131,60 €")
    e2 = E("Vrai ou faux ? Je coche.", vf(["Le billet est en 1re classe.", "Le voyageur a plus de 26 ans.", "Il peut prendre n'importe quel train le 12/06.", "Il doit avoir sa carte d'identité."]), ["lis", "coche"], 1, "B", sol="Faux (2e classe) · Faux (moins de 26 ans) · Vrai (tous les trains du jour) · Vrai")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Un billet de train</h2>{e}{e2}', "Document de la vie")
    pan = panneau([("09:15", "IC", "Bruxelles-Midi", "4", "+20 min"), ("09:22", "L", "Charleroi-Central", "2", ""), ("09:32", "IC", "Bruxelles-Midi", "4", ""), ("09:37", "IC", "Liège-Guillemins", "6", ""), ("09:45", "L", "Dinant", "1", "supprimé"), ("09:52", "IC", "Luxembourg", "5", "voie 7")])
    e = E("Je lis le panneau des départs de la gare de Namur. Il est 9 h 12. Je réponds.", pan + f"<p class='mt2'>1. Quel train a du retard ? De combien ? {blank('l')}</p><p>2. Je vais à Dinant : quel est le problème ? {blank('l')}</p><p>3. Le train pour Luxembourg part de quelle voie ? {blank()} Pourquoi faut-il faire attention ? {blank('l')}</p><p>4. Je vais à Liège : à quelle heure et de quelle voie part mon train ? {blank('l')}</p><p>5. Je veux arriver le plus vite possible à Bruxelles : quel train je prends ? Pourquoi ? {blank('xl')}</p>", ["lis", "ecris"], 2, "B",
          sol="1. le train de 9 h 15 pour Bruxelles-Midi, 20 minutes — 2. le train est supprimé — 3. voie 7 ; il y a un changement de voie (normalement voie 5) — 4. à 9 h 37, voie 6 — 5. le train de 9 h 32 : il partira avant le train de 9 h 15, qui a 20 minutes de retard (départ vers 9 h 35)")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Le panneau d\'affichage</h2>{e}', "Document de la vie")
    tec = table(["Arrêt", "Lu-Ve", "", "", "Sa", "Di"], [["École (départ)", "15:35", "16:05", "16:35", "—", "—"], ["Place communale", "15:42", "16:12", "16:42", "—", "—"], ["Hôpital", "15:50", "16:20", "16:50", "—", "—"], ["Gare (arrivée)", "15:58", "16:28", "16:58", "—", "—"]], ["56mm", "26mm", "26mm", "26mm", "24mm", "24mm"])
    e = E("Je lis l'horaire du bus scolaire (ligne 12, horaire fictif). Je réponds.", tec + "<p class='xs muted'>— = pas de bus · Lu-Ve = du lundi au vendredi</p>" + "<p>1. Les cours finissent à 15 h 50. Quel bus je peux prendre ? ______ 2. Combien de temps dure le trajet de l'école à la gare ? ______ 3. Le samedi, il y a un bus ? ______ 4. Mon train part de la gare à 16 h 40. Quel bus je prends au plus tard ? ______</p>", ["lis", "ecris"], 2, "B",
          sol="1. le bus de 16 h 05 — 2. 23 minutes — 3. non — 4. le bus de 16 h 05 (arrivée 16 h 28)")
    e2 = E("Je donne un conseil à un nouvel élève pour venir à l'école en bus (3 phrases avec si / devoir / impératif).", lines(3), ["ecris"], 2, "C", sol="Ex. : Si tu habites près de la gare, prends le bus 12. Tu dois valider ta carte en montant. Si le bus est en retard, préviens l'éducateur.")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Un horaire de bus</h2>{e}{e2}', "Document de la vie")

    # ---------- Sons ----------
    e = E("Les sons [y] et [u]. J'écoute et je répète.", "<div class='grid2'><div class='card c'><div class='huge'>[y] le bus 🚌</div><p>les lèvres en avant, la langue en avant<br>le b<b>u</b>s · la r<b>u</b>e · t<b>u</b> · le m<b>u</b>sée · la min<b>u</b>te · s<b>u</b>pprimé</p></div><div class='card c'><div class='huge'>[u] la route 🛣️</div><p>les lèvres rondes, la langue en arrière<br>la r<b>ou</b>te · le j<b>ou</b>r · s<b>ou</b>s · le retour · le parc<b>ou</b>rs · Toussaint</p></div></div><div class='astuce'>[y] s'écrit <b>u</b> · [u] s'écrit <b>ou</b>. Truc : dis [i] en arrondissant les lèvres → [y].</div>", ["ecoute", "repete"], 1, "A",
          script="Paires minimales : tu / tout · rue / roue · dessus / dessous · vu / vous · pur / pour. Faire sentir la position de la langue (en avant pour [y], en arrière pour [u]).", sol="Activité orale.")
    e2 = E("J'écoute : [y] ou [u] ? Je coche.", checks(8, ["[y] bus", "[u] route"]), ["ecoute", "coche"], 2, "A", script="1. la rue — 2. la roue — 3. tu — 4. tout — 5. dessus — 6. dessous — 7. le musée — 8. le retour",
           sol="1. [y] — 2. [u] — 3. [y] — 4. [u] — 5. [y] — 6. [u] — 7. [y] — 8. [u]")
    e3 = E("Je lis vite et bien.", "<div class='card big c' style='line-height:1.8'>Sur la route, le bus roule sous la pluie ;<br>tu as vu ? Tout le monde court vers le musée !</div>", ["lis", "parle"], 2, "B", sol="Lecture à voix haute.")
    e4 = E("J'écoute et j'écris u ou ou.", "<p class='big'>1. la r___te · 2. le b___s · 3. le j___r · 4. s___pprimé · 5. le ret___r · 6. la min___te · 7. t___jours · 8. le m___sée</p>", ["ecoute", "complete"], 2, "A", script="1. la route — 2. le bus — 3. le jour — 4. supprimé — 5. le retour — 6. la minute — 7. toujours — 8. le musée",
           sol="1. ou — 2. u — 3. ou — 4. u — 5. ou — 6. u — 7. ou — 8. u")
    b.page(f'<h2>J\'écoute bien · [y] et [u]</h2>{e}{e2}{e3}{e4}', "Sons")
